import bisect
adj={}; pair_times={}
for u,v,t in events:
    adj.setdefault(u,[]).append((t,v)); adj.setdefault(v,[]).append((t,u))
    pair_times.setdefault((u,v) if u<v else (v,u),[]).append(t)
for k in adj: adj[k].sort()
for k in pair_times: pair_times[k].sort()

def closures(lo,hi,delta=800):
    res=[]
    for a,b,tc in events:
        if tc<lo or tc>hi: continue
        best=None
        for t1,c in adj[a]:
            if t1>=tc: break
            if c==b: continue
            key=(b,c) if b<c else (c,b)
            L=pair_times.get(key)
            if not L: continue
            i=bisect.bisect_left(L,tc)-1
            if i<0: continue
            t2=L[i]
            m=t1 if t1>t2 else t2
            lag=tc-m
            if 0<lag<=delta and (best is None or lag<best[0]):
                best=(lag,c,t1,t2)
        if best: res.append((a,b,tc,best))
    return res

