def last_before(x,y,tc):
    L=pt.get((x,y) if x<y else (y,x))
    if not L: return None
    i=bisect_left(L,tc)-1
    return L[i] if i>=0 else None

def closures(lo,hi,delta=800):
    res=[]
    for a,b,tc in events:
        if tc<lo or tc>hi: continue
        best=None
        for (p,q) in ((a,b),(b,a)):
            T=adjt[p]; A=adj[p]
            i=bisect_left(T,tc-delta)
            j=bisect_left(T,tc)
            for k in range(i,j):
                t1,c=A[k]
                if c==q or c==p: continue
                t2=last_before(q,c,tc)
                if t2 is None: continue
                m=t1 if t1>t2 else t2
                lag=tc-m
                if 0<lag<=delta and (best is None or lag<best[0]):
                    best=(lag,c,t1,t2)
        if best: res.append((a,b,tc,best))
    return res

