def build(ev):
    adj={};pt={}
    for u,v,t in ev:
        adj.setdefault(u,[]).append((t,v)); adj.setdefault(v,[]).append((t,u))
        k=(u,v) if u<v else (v,u); pt.setdefault(k,[]).append(t)
    for k in adj: adj[k].sort()
    for k in pt: pt[k].sort()
    return adj,pt

def count(ev,lo,hi,delta=D,collect=False):
    adj,pt=build(ev); adjt={k:[t for t,_ in v] for k,v in adj.items()}
    res=[]
    for a,b,tc in ev:
        if tc<lo or tc>hi: continue
        best=None
        for p,q in ((a,b),(b,a)):
            T=adjt[p];A=adj[p]
            for k in range(bl(T,tc-delta),bl(T,tc)):
                t1,c=A[k]
                if c==q: continue
                L=pt.get((q,c) if q<c else (c,q))
                if not L: continue
                i=bl(L,tc)-1
                if i<0: continue
                t2=L[i]; m=t1 if t1>t2 else t2; lag=tc-m
                if 0<lag<=delta and (best is None or lag<best[0]): best=(lag,c,t1,t2)
        if best: res.append((a,b,tc,best))
    return res

